{
  "name": "javascript-workspace",
  "version": "1.0.0",
  "type": "module",
  "scripts": {
    "test": "node --test"
  }
}

console.log("=====================================================");
console.log("💛 Welcome to 00 - JavaScript Setup & Runtime Check!");
console.log("=====================================================");
console.log(`✔ Node.js Version: ${process.version}`);
console.log(`✔ Architecture    : ${process.arch}`);
console.log(`✔ Platform        : ${process.platform}`);
console.log("\n👉 Next: Head over to 01-v8-engine-and-memory-layout/index.js");

console.log("=== 01: V8 Engine Pipeline & Memory Layout ===");
console.log("V8 Execution: Parser -> AST -> Ignition (Bytecode) -> TurboFan (JIT)");

const mem = process.memoryUsage();
console.log("Memory Usage (MB):");
console.log(`- Heap Used : ${(mem.heapUsed / 1024 / 1024).toFixed(2)} MB`);
console.log(`- Heap Total: ${(mem.heapTotal / 1024 / 1024).toFixed(2)} MB`);
console.log(`- RSS Total : ${(mem.rss / 1024 / 1024).toFixed(2)} MB`);

console.log("=== 02: Execution Context & Hoisting ===");

// var is hoisted and initialized to undefined
console.log("Hoisted var a:", typeof a, a); // undefined
var a = 10;

// let and const are hoisted but UNINITIALIZED (in Temporal Dead Zone - TDZ)
// console.log(b); // ReferenceError!
let b = 20;

console.log("After initialization: a =", a, "b =", b);

function createCounter(initial = 0) {
  let count = initial; // Private state closed over
  return {
    increment: () => ++count,
    decrement: () => --count,
    getCount: () => count,
  };
}

const counter = createCounter(10);
console.log("=== 03: Closures & Lexical Scopes ===");
console.log("Count:", counter.increment());
console.log("Count:", counter.increment());

const user = {
  name: "Alice",
  greetRegular: function () { return `Hello, ${this.name}`; },
  greetArrow: () => `Hello, ${this?.name}`,
};

const context = { name: "Navnath" };

console.log("=== 05: The 'this' Keyword Binding Rules ===");
console.log("Implicit:", user.greetRegular());
console.log("Explicit call():", user.greetRegular.call(context));
console.log("Arrow function (lexical):", user.greetArrow());

function Animal(name) {
  this.name = name;
}
Animal.prototype.speak = function () {
  return `${this.name} makes a sound.`;
};

const dog = new Animal("Rex");
console.log("=== 06: Prototypes & Prototype Chain ===");
console.log(dog.speak());
console.log("dog prototype link:", Object.getPrototypeOf(dog) === Animal.prototype);

const original = { a: 1, nested: { b: 2 } };

// Deep Clone (native in modern JS)
const deepCloned = structuredClone(original);
deepCloned.nested.b = 99;

console.log("=== 07: Objects & structuredClone ===");
console.log("Original nested.b:", original.nested.b); // 2 (Untouched!)
console.log("Cloned nested.b  :", deepCloned.nested.b); // 99

const nums = [1, 2, 3, 4, 5];
const sumOfEvenSquares = nums
  .filter(x => x % 2 === 0)
  .map(x => x ** 2)
  .reduce((acc, x) => acc + x, 0);

console.log("=== 08: Array Functional Pipeline ===");
console.log("Sum of even squares:", sumOfEvenSquares);

async function fetchPipeline() {
  const p1 = Promise.resolve("Result 1");
  const p2 = Promise.resolve("Result 2");
  const results = await Promise.all([p1, p2]);
  return results;
}

fetchPipeline().then(res => {
  console.log("=== 09: Promises & Async/Await ===");
  console.log("Combined Promise Results:", res);
});

console.log("1. Synchronous Code");

setTimeout(() => {
  console.log("4. Macrotask (setTimeout)");
}, 0);

queueMicrotask(() => {
  console.log("3. Microtask (queueMicrotask)");
});

Promise.resolve().then(() => {
  console.log("2. Microtask (Promise .then)");
});

function* idGenerator() {
  let id = 1;
  while (true) {
    yield `ID_${id++}`;
  }
}

const gen = idGenerator();
console.log("=== 11: Generators & Yield ===");
console.log(gen.next().value);
console.log(gen.next().value);

const iterableObj = {
  data: ["A", "B", "C"],
  [Symbol.iterator]() {
    let index = 0;
    return {
      next: () => ({
        value: this.data[index++],
        done: index > this.data.length,
      }),
    };
  },
};

console.log("=== 12: Well-Known Symbols (Symbol.iterator) ===");
for (const item of iterableObj) {
  console.log("Item:", item);
}

const map = new Map();
const keyObj = { id: 1 };
map.set(keyObj, "Active Session");

console.log("=== 13: Map, Set, WeakMap & WeakSet ===");
console.log("Map value for object key:", map.get(keyObj));

const target = { price: 100 };

const proxy = new Proxy(target, {
  get(target, prop, receiver) {
    console.log(`[Proxy Trap] Reading property '${String(prop)}'`);
    return Reflect.get(target, prop, receiver);
  },
  set(target, prop, value, receiver) {
    if (prop === "price" && value < 0) throw new Error("Price cannot be negative");
    return Reflect.set(target, prop, value, receiver);
  },
});

console.log("=== 14: Metaprogramming with Proxy & Reflect ===");
console.log("Price:", proxy.price);
proxy.price = 150;

const buffer = Buffer.from("Trak JavaScript Track", "utf-8");
console.log("=== 15: Streams, Buffers & Binary Data ===");
console.log("Buffer raw bytes:", buffer);
console.log("Buffer hex string:", buffer.toString("hex"));

const data = { user: { profile: null } };

// Optional Chaining & Nullish Coalescing
const bio = data?.user?.profile?.bio ?? "Default Bio";
console.log("=== 16: Modern ECMAScript Features ===");
console.log("Extracted Bio:", bio);

// Debounce helper
function debounce(fn, delayMs) {
  let timeoutId;
  return function (...args) {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => fn.apply(this, args), delayMs);
  };
}

const debouncedLog = debounce((msg) => console.log("Debounced:", msg), 100);
console.log("=== 17: DOM, Event Delegation & Debouncing ===");
debouncedLog("Search input changed");

export function calculateTotal(prices) {
  return prices.reduce((acc, p) => acc + p, 0);
}

console.log("=== 18: Modules (ESM vs CommonJS) ===");
console.log("Total:", calculateTotal([10, 20, 30]));

export function multiply(a, b) {
  return a * b;
}

import assert from "node:assert";
import test from "node:test";
import { multiply } from "./calc.js";

test("multiplies numbers", () => {
  assert.strictEqual(multiply(4, 5), 20);
});

console.log("=====================================================");
console.log("🎯 21: High-Yield JavaScript Interview Questions & Drills");
console.log("=====================================================");
console.log("1. Event Loop: Microtasks (Promises) always run before Macrotasks (setTimeout).");
console.log("2. Closures: Functions retain access to their lexical scope even when executed outside.");
console.log("3. this binding: 5 rules - new, explicit, implicit, default, and lexical arrow.");
console.log("4. Hoisting & TDZ: let/const are in Temporal Dead Zone until initialized.");
console.log("5. structuredClone: Native deep copy handling cyclic references & TypedArrays.");
console.log("\n🚀 You have completed the complete JavaScript Mastery curriculum!");
